 int pageNo=1,y=95;android.graphics.pdf.PdfDocument.Page page=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,pageNo).create());
 decorate(page.getCanvas(),pageNo);for(String line:lines){for(String part:line.split("\\n",-1)){String rest=part;do{int n=p.breakText(rest,true,505,null);if(n==0&&rest.length()>0)n=1;if(y>770){doc.finishPage(page);page=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,++pageNo).create());y=95;decorate(page.getCanvas(),pageNo);}page.getCanvas().drawText(rest.substring(0,n),45,y,p);y+=19;rest=rest.substring(n);}while(!rest.isEmpty());}}
 if(y>650){doc.finishPage(page);page=doc.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(595,842,++pageNo).create());y=95;decorate(page.getCanvas(),pageNo);}for(String key:new String[]{"banca","banca2"}){y+=45;page.getCanvas().drawLine(45,y,550,y,p);y+=18;page.getCanvas().drawText(j.optString(key),45,y,p);}
